CREATE TABLE production_order (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,created_by BIGINT NULL,updated_by BIGINT NULL,version BIGINT NOT NULL DEFAULT 0,order_no VARCHAR(64) NOT NULL,product_material_id BIGINT NOT NULL,product_code VARCHAR(50) NOT NULL DEFAULT '',product_name VARCHAR(120) NOT NULL DEFAULT '',unit VARCHAR(10) NOT NULL DEFAULT '',planned_quantity DECIMAL(12,0) NOT NULL,bom_id BIGINT NOT NULL,bom_code VARCHAR(50) NOT NULL DEFAULT '',bom_revision INT NULL,issue_warehouse_id BIGINT NOT NULL,issue_warehouse_name VARCHAR(120) NOT NULL DEFAULT '',receipt_warehouse_id BIGINT NOT NULL,receipt_warehouse_name VARCHAR(120) NOT NULL DEFAULT '',status VARCHAR(24) NOT NULL DEFAULT 'DRAFT',remark VARCHAR(500) NOT NULL DEFAULT '',confirmed_at DATETIME(3) NULL,issued_at DATETIME(3) NULL,reported_at DATETIME(3) NULL,completed_at DATETIME(3) NULL,cancelled_at DATETIME(3) NULL,deleted_at DATETIME(3) NULL,
 UNIQUE KEY uq_production_no(order_no),KEY ix_production_status(status,created_at,id),FOREIGN KEY(product_material_id) REFERENCES material(id),FOREIGN KEY(bom_id) REFERENCES bom(id),FOREIGN KEY(issue_warehouse_id) REFERENCES warehouse(id),FOREIGN KEY(receipt_warehouse_id) REFERENCES warehouse(id),CHECK(planned_quantity>0),CHECK(status IN('DRAFT','READY_TO_ISSUE','IN_PRODUCTION','PENDING_INBOUND','COMPLETED','CANCELLED')),FOREIGN KEY(created_by) REFERENCES sys_user(id),FOREIGN KEY(updated_by) REFERENCES sys_user(id),CHECK(version>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE production_material_snapshot (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,production_order_id BIGINT NOT NULL,line_no INT NOT NULL,material_id BIGINT NOT NULL,material_code VARCHAR(50) NOT NULL,material_name VARCHAR(120) NOT NULL,unit VARCHAR(10) NOT NULL,quantity_per DECIMAL(12,0) NOT NULL,required_quantity DECIMAL(12,0) NOT NULL,
 UNIQUE KEY uq_snapshot_material(production_order_id,material_id),UNIQUE KEY uq_snapshot_line(production_order_id,line_no),FOREIGN KEY(production_order_id) REFERENCES production_order(id),FOREIGN KEY(material_id) REFERENCES material(id),CHECK(quantity_per>0),CHECK(required_quantity>0),CHECK(line_no>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
